get_dashboard_kpi_options.code:
import (
	"fmt"
)

resp, err := client.DashboardKPIs().GetDashboardKPIOptions(ctx, nil)
if err != nil {
	log.Fatal(err)
}
body := resp.Map().(map[string]any)
fmt.Println(body["min"], body["max"], body["selected"])
for _, row := range body["groups"].([]any) {
	group := row.(map[string]any)
	fmt.Println(group["key"], group["label"])
}

get_dashboard_kpi_selection.code:
import (
	"fmt"
)

resp, err := client.DashboardKPIs().GetDashboardKPISelection(ctx, map[string]any{"duration": "last_7_days"}, nil)
if err != nil {
	log.Fatal(err)
}
body := resp.Map().(map[string]any)
for _, row := range body["selected"].([]any) {
	kpi := row.(map[string]any)
	fmt.Println(kpi["position"], kpi["label"], kpi["value"], kpi["change_percent"], kpi["direction"])
}

